// iosrt sample: an app started the pre-storyboard way. Info.plist names
// NSMainNibFile = MainWindow; that nib (an NSKeyedArchiver archive, the old
// ibtool format, generated by tools/mknib.py --main-window) creates the app
// delegate, the window and its views, and wires outlets and an action.
// main() passes no delegate class name.
#import <UIKit/UIKit.h>

@interface KeyedBadge : UIView
@end
@implementation KeyedBadge
- (void)awakeFromNib { [super awakeFromNib]; NSLog(@"KeyedBadge awakeFromNib, frame %@", NSStringFromCGRect(self.frame)); }
@end

@interface KeyedNibController : NSObject <UIApplicationDelegate>
@property (nonatomic, strong) UIWindow *window;
@property (nonatomic, strong) UILabel *label;
@property (nonatomic) int presses;
@end
@implementation KeyedNibController
- (void)awakeFromNib { NSLog(@"controller awakeFromNib: window outlet %@, label outlet %@", self.window ? @"set" : @"missing", self.label.text); }
- (BOOL)application:(UIApplication *)app didFinishLaunchingWithOptions:(NSDictionary *)opts {
    NSLog(@"didFinishLaunching: delegate came from the nib: %d, window %@ with %lu subviews, background alpha %.1f",
          app.delegate == self, NSStringFromCGRect(self.window.frame), (unsigned long)self.window.subviews.count, CGColorGetAlpha(self.window.backgroundColor.CGColor));
    [self.window makeKeyAndVisible];
    return YES;
}
- (void)pressed:(id)sender {
    self.presses++;
    self.label.text = [NSString stringWithFormat:@"pressed %d", self.presses];
    NSLog(@"pressed: %@ -> '%@' (outlets alive: %d)", NSStringFromClass([sender class]), self.label.text, self.label != nil && self.window != nil);
}
@end

int main(int argc, char *argv[]) {
    @autoreleasepool { return UIApplicationMain(argc, argv, nil, nil); }
}
